PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?person ?birthDate
WHERE {
  { dbr:Marco_de_Luigi dbp:birthDate ?birthDate . BIND(dbr:Marco_de_Luigi AS ?person) }
  UNION
  { dbr:Fabio_Maistro dbp:birthDate ?birthDate . BIND(dbr:Fabio_Maistro AS ?person) }
}
LIMIT 100

