PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate
WHERE {
  VALUES ?film { <http://dbpedia.org/resource/A.P.E.X.> <http://dbpedia.org/resource/Quax_in_Africa> }

  # director (prefer dbp, fallback to dbo)
  OPTIONAL { ?film dbp:director ?director . }
  OPTIONAL { ?film dbo:director ?director . }
  FILTER (BOUND(?director))

  # director birth date (prefer dbo, fallback to dbp)
  OPTIONAL { ?director dbo:birthDate ?birthDate . }
  OPTIONAL { ?director dbp:birthDate ?birthDate . }
  FILTER (BOUND(?birthDate))

  # labels for readability
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER (lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER (lang(?directorLabel) = "en") }
}
ORDER BY ASC(?birthDate)
LIMIT 1

sparql:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director ?birthDate
WHERE {
  VALUES ?film { dbr:The_Boss_and_the_Worker <http://dbpedia.org/resource/Claire's_Knee> }

  { ?film dbp:director ?director } UNION { ?film dbo:director ?director }

  { ?director dbp:birthDate ?birthDate } UNION { ?director dbo:birthDate ?birthDate }
}
ORDER BY DESC(?birthDate)
LIMIT 1

